async (page) => {
  const errors = [], result = {}
  const onError = error => errors.push(error.message)
  page.on('pageerror', onError)
  await page.route('**/api/visual-curator/resource**', route => route.fulfill({ status: 200, contentType: 'image/svg+xml', body: '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="240"><rect width="400" height="240" fill="#526956"/></svg>' }))
  await page.goto('http://127.0.0.1:3094/')
  await page.setViewportSize({ width: 1440, height: 960 })
  await page.getByRole('button', { name: '开始视觉分析', exact: true }).waitFor()
  await page.evaluate(() => { window.incrementalFixture.state.holdStatus = true; window.incrementalFixture.state.holdStart = true })
  await page.getByRole('button', { name: '开始视觉分析', exact: true }).click()
  const start = page.locator('.vc-analysis-start-modal')
  await start.locator('.vc-analysis-plan-loading').waitFor()
  result.immediateStartSkeleton = await start.locator('.vc-skeleton-fill').count() === 3
  await start.getByRole('button', { name: '取消', exact: true }).click()
  await start.waitFor({ state: 'hidden' })
  await page.evaluate(() => window.incrementalFixture.releaseStatus())
  result.planningCanCancel = await page.evaluate(() => window.incrementalFixture.state.launches.length === 0)
  await page.evaluate(() => { window.incrementalFixture.state.holdStatus = true })
  await page.getByRole('button', { name: '开始视觉分析', exact: true }).click()
  await start.locator('.vc-analysis-plan-loading').waitFor()
  result.opaqueStartSurface = await start.evaluate(element => { const style = getComputedStyle(element, '::before'); return style.backdropFilter === 'none' && !style.backgroundColor.includes('rgba') })
  await page.evaluate(() => window.incrementalFixture.releaseStatus())
  await start.locator('.vc-create-form').waitFor()
  await start.locator('.vc-task-footer button').last().click()
  result.startButtonBusy = await start.locator('.vc-task-footer button[aria-busy="true"]').count() === 1
  await page.evaluate(() => window.incrementalFixture.releaseStart())
  await start.waitFor({ state: 'hidden' })
  result.acceptedOnce = await page.evaluate(() => window.incrementalFixture.state.launches.length === 1)
  await page.getByText('找图与裁剪', { exact: true }).click()
  await page.locator('.vc-image-workspace[data-view="execution"]').waitFor()
  const reads = await page.evaluate(() => window.incrementalFixture.state.statusReads)
  await page.evaluate(() => window.incrementalFixture.advanceAnalysisProgress())
  await page.waitForTimeout(100)
  result.inactiveEligibilityNotFetched = await page.evaluate(() => window.incrementalFixture.state.statusReads) === reads
  await page.getByText('参考与画像', { exact: true }).click()
  await page.evaluate(() => window.incrementalFixture.showAnalysis())
  const dialog = page.locator('.vc-analysis-modal'), context = dialog.locator('.vc-context-usage:visible')
  await dialog.waitFor()
  const originalRun = await page.evaluate(() => window.incrementalFixture.getAnalysisRunId())
  result.reportedContextRetained = (await context.innerText()).includes('40,000') && (await context.innerText()).includes('上次已报告的请求')
  await page.evaluate(() => window.incrementalFixture.nextRequest())
  result.pendingContextDoesNotBlank = (await context.innerText()).includes('40,000') && !(await context.innerText()).includes('—')
  await page.evaluate(() => { window.incrementalFixture.state.holdPause = true })
  await dialog.getByRole('button', { name: '暂停分析', exact: true }).click()
  result.pausingFeedback = await dialog.getByRole('button', { name: '正在暂停', exact: true }).isDisabled()
  await page.evaluate(() => window.incrementalFixture.releasePause())
  await dialog.getByRole('button', { name: '继续分析', exact: true }).waitFor()
  result.continueAvailable = true
  await dialog.getByRole('button', { name: '继续分析', exact: true }).click()
  await dialog.getByRole('button', { name: '暂停分析', exact: true }).waitFor()
  result.sameRunContinues = await page.evaluate(() => window.incrementalFixture.getAnalysisRunId()) === originalRun && (await context.innerText()).includes('40,000')
  await page.goto('http://127.0.0.1:3096/')
  await page.evaluate(() => { window.feedbackFixture.setMode('workbench'); window.feedbackFixture.setScenario('batches'); window.feedbackFixture.setAnalysisRunning(true) })
  await page.locator('[data-search-batch]').first().waitFor()
  result.savedMatchesDuringAnalysis = await page.locator('[data-search-batch]').count() === 2
  result.thumbnailCards = await page.locator('.vc-search-batch .vc-reference-preview .vc-image-preview img').evaluateAll(images => images.length === 2 && images.every(image => new URL(image.src).searchParams.get('preview') === 'thumbnail'))
  await page.locator('.vc-search-batch .vc-image-preview').first().click()
  const lightbox = page.getByRole('dialog', { name: '预览图片', exact: true })
  await lightbox.waitFor()
  await lightbox.locator('img').first().waitFor()
  result.largerPreviewOnDemand = await lightbox.locator('img').evaluateAll(images => images.some(image => image.src.includes('/api/visual-curator/resource?') && !new URL(image.src).searchParams.has('preview')))
  result.errors = errors
  const response = await page.request.get('http://127.0.0.1:3096/analysis-performance-ui.expected.json'), expected = await response.json()
  page.off('pageerror', onError)
  if (Object.keys(result).length !== Object.keys(expected).length || Object.entries(expected).some(([key, value]) => JSON.stringify(result[key]) !== JSON.stringify(value))) throw new Error(JSON.stringify({ expected, actual: result }))
  return result
}
